from itertools import combinations

def solve(g):
 cells={(r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v==8}
 options=[]
 # square tiles
 for r,c in cells:
  s={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
  if s<=cells: options.append((s,1,'S'))
 # L tile within 2x2, missing corner mapping
 mapping={0:2,2:3,1:4,3:5} # missing TL,TR,BL,BR respectively
 for r,c in cells:
  for miss,col in mapping.items():
   box={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
   s=box-{(r+miss//2,c+miss%2)}
   if s<=cells: options.append((s,col,'L'))
 options.sort(key=lambda x: 0 if x[2]=='S' else 1)
 sols=[]
 def rec(rem, out):
  if not rem:
   sols.append(out.copy());return
  if len(sols)>1000:return
  cell=min(rem)
  for shape,col,_ in options:
   if cell in shape and shape<=rem:
    for r,c in shape: out[r][c]=col
    rec(rem-shape,out)
    for r,c in shape: out[r][c]=0
 rec(cells, [[0]*len(g[0]) for _ in g])
 return sols

