 "content": "def transform(grid):
    """Tile each 8-cell region with 2x2 squares and L-triominoes.

    Squares are color 1. For an L formed by removing a corner from a 2x2
    box, the color identifies the missing corner: TL=2, BL=3, TR=4, BR=5.
    """
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    tiles = []
    for r in range(h - 1):
        for c in range(w - 1):
            box = {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}
            if box <= cells:
                tiles.append((box, 1))
            # Color according to the omitted corner.
            for missing, color in (((r, c), 2), ((r + 1, c), 3),
                                   ((r, c + 1), 4), ((r + 1, c + 1), 5)):
                shape = box - {missing}
                if shape <= cells:
                    tiles.append((shape, color))

    # Exact-cover search; the demos have unique tilings under these pieces.
    result = [[0] * w for _ in range(h)]
    def search(remaining):
        if not remaining:
            return True
        cell = min(remaining)
        for shape, color in tiles:
            if cell in shape and shape <= remaining:
                for r, c in shape:
                    result[r][c] = color
                if search(remaining - shape):
                    return True
                for r, c in shape:
                    result[r][c] = 0
        return False

    if not search(cells):
        raise ValueError("8-cells cannot be tiled by the demonstrated pieces")
    return result
